The chain of consumer types for which an instance is created, ordered from the immediate consumer down to the composition type.
Cannot be used outside the binding setup. Guaranteed to contain at least one element.


using System.Linq;

var box = new Composition().Box;
// Output: ShroedingersCat, CardboardBox`1, Composition

static void Setup() =>
    DI.Setup(nameof(Composition))
    .Bind().To(ctx => new Log(ctx.ConsumerTypes))
    .Bind().To<ShroedingersCat>()
    .Bind().To<CardboardBox<TT>>()
    .Root<CardboardBox<ShroedingersCat>>("Box");

public class Log
{
    public Log(Type[] types) =>
        Console.WriteLine(string.Join(", ", types.Select(type => type.Name)));
}

public record CardboardBox<T>(T Content);

public record ShroedingersCat(Log log);

The immediate consumer type for which the instance is created. Cannot be used outside the binding setup.


var box = new Composition().Box;
// Output: ShroedingersCat

static void Setup() =>
    DI.Setup(nameof(Composition))
    .Bind().To(ctx => new Log(ctx.ConsumerType))
    .Bind().To<ShroedingersCat>()
    .Bind().To<CardboardBox<TT>>()
    .Root<CardboardBox<ShroedingersCat>>("Box");

public class Log
{
    public Log(Type type) =>
        Console.WriteLine(type.Name);
}

public record CardboardBox<T>(T Content);

public record ShroedingersCat(Log log);

Gets the synchronization object used to control thread-safe access during composition.
Use it to guard manual construction/override logic in factory delegates.


DI.Setup(nameof(Composition))
    .Bind<IDependency>().To(ctx =>
    {
        lock (ctx.Lock)
        {
            ctx.Inject(out Dependency dependency);
            dependency.Initialize();
            return dependency;
        }
    })

Gets the number of dependencies in the current composition context.
This property provides information about how many dependencies are available
for injection in the current factory context. Cannot be used outside the binding setup.


DI.Setup("Composition")
    .Bind<IService>()
    .To(ctx =>
    {
        var dependencyCount = ctx.DependencyCount;
        Console.WriteLine($"Dependencies available: {dependencyCount}");
        ctx.Inject<IDependency>(out var dependency);
        return new Service(dependency);
    })

Gets whether a lock is required in the current context.
This property indicates whether synchronization is needed for thread-safe access during composition.
Cannot be used outside the binding setup.


DI.Setup("Composition")
    .Bind<IService>()
    .To(ctx =>
    {
        if (ctx.IsLockRequired)
        {
            lock (ctx.Lock)
            {
                ctx.Inject<IDependency>(out var dependency);
                return new Service(dependency);
            }
        }
        else
        {
            ctx.Inject<IDependency>(out var dependency);
            return new Service(dependency);
        }
    })

